(function(){
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let loading=false,state=null,defaults=null;
const fields=['system_name','header_text','qr_caption','footer_text','paper_height','qr_size','brand_font_size','queue_font_size','department_font_size','service_font_size','detail_font_size'];
const checks=['show_service','show_slot','show_date','show_reference','show_qr','show_qr_caption','hide_duplicate_service'];
function preview(root){const p=root.querySelector('[data-ticket-preview]'),v=state;p.style.setProperty('--brand-size',`${v.brand_font_size}px`);p.style.setProperty('--queue-size',`${v.queue_font_size}px`);p.style.setProperty('--dept-size',`${v.department_font_size}px`);p.style.setProperty('--service-size',`${v.service_font_size}px`);p.style.setProperty('--detail-size',`${v.detail_font_size}px`);p.style.setProperty('--qr-size',`${v.qr_size}px`);p.innerHTML=`<strong class="ticket-preview-brand">${e(v.system_name)}</strong><span>${e(v.header_text)}</span><b>OP-001</b><hr><h4>ตรวจโรคทั่วไป</h4>${v.show_service?'<h5>ตรวจโรคทั่วไป</h5>':''}${v.show_slot?'<p>เริ่มส่งตรวจ 08:00–09:00 น.</p>':''}${v.show_date?'<p>22 ตุลาคม 2569</p>':''}${v.show_reference?'<small>เลขอ้างอิง KQ-261022-ABC123</small>':''}${v.show_qr?'<i class="ticket-preview-qr">QR</i>':''}${v.show_qr&&v.show_qr_caption?`<p>${e(v.qr_caption)}</p>`:''}<hr><small>${e(v.footer_text)}</small>`}
function read(root){fields.forEach(k=>state[k]=root.querySelector(`[name="${k}"]`).type==='number'?Number(root.querySelector(`[name="${k}"]`).value):root.querySelector(`[name="${k}"]`).value.trim());checks.forEach(k=>state[k]=root.querySelector(`[name="${k}"]`).checked);preview(root)}
function form(root){root.innerHTML=`<form class="ticket-template-form"><div class="ticket-template-controls"><div class="settings-group-head"><div><span class="eyebrow">QUEUE TICKET DESIGN</span><h3>ออกแบบบัตรคิว</h3><p>กำหนดข้อความ ขนาด และรายการที่ต้องการพิมพ์บนกระดาษ 80 มม.</p></div></div><div class="form-grid"><label>ชื่อระบบ<input name="system_name" maxlength="40"></label><label>หัวบัตร<input name="header_text" maxlength="100"></label><label>ข้อความใต้ QR<input name="qr_caption" maxlength="100"></label><label>ข้อความท้ายบัตร<input name="footer_text" maxlength="140"></label><label>ความยาวกระดาษ<input name="paper_height" type="number" min="260" max="700"><span>หน่วย 1/100 นิ้ว</span></label><label>ขนาด QR<input name="qr_size" type="number" min="70" max="160"></label><label>ชื่อระบบ<input name="brand_font_size" type="number" min="9" max="22"></label><label>เลขคิว<input name="queue_font_size" type="number" min="20" max="48"></label><label>ชื่อแผนก<input name="department_font_size" type="number" min="9" max="24"></label><label>ชื่อบริการ<input name="service_font_size" type="number" min="8" max="20"></label><label>รายละเอียด<input name="detail_font_size" type="number" min="7" max="16"></label></div><fieldset class="ticket-options"><legend>ข้อมูลที่แสดง</legend>${[['show_service','ชื่อบริการ'],['show_slot','ช่วงเวลา'],['show_date','วันที่ พ.ศ.'],['show_reference','เลขอ้างอิง'],['show_qr','QR ติดตามคิว'],['show_qr_caption','ข้อความใต้ QR'],['hide_duplicate_service','ซ่อนชื่อบริการเมื่อซ้ำกับชื่อแผนก']].map(([k,t])=>`<label><input type="checkbox" name="${k}"> ${t}</label>`).join('')}</fieldset><div class="auth-error hidden" data-ticket-error></div><div class="ticket-template-actions"><button type="button" class="secondary" data-ticket-reset>คืนค่าเริ่มต้น</button><button class="primary" type="submit">บันทึกแบบฟอร์ม</button></div></div><aside><h4>ตัวอย่างก่อนพิมพ์</h4><div class="ticket-preview" data-ticket-preview></div><small>ตัวอย่างใช้ฟอนต์ Sarabun และวันที่ พ.ศ. การพิมพ์จริงใช้ข้อมูลคิวปัจจุบัน</small></aside></form>`;fill(root)}
function fill(root){fields.forEach(k=>root.querySelector(`[name="${k}"]`).value=state[k]);checks.forEach(k=>root.querySelector(`[name="${k}"]`).checked=!!state[k]);preview(root);root.querySelectorAll('input').forEach(x=>x.addEventListener('input',()=>read(root)));root.querySelector('[data-ticket-reset]').onclick=()=>{state={...defaults};fill(root)};root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();read(root);const btn=ev.submitter,error=root.querySelector('[data-ticket-error]');btn.disabled=true;error.classList.add('hidden');try{const r=await kqApi('ticket-template-settings',{method:'POST',body:JSON.stringify(state)});state=r.data;showToast('บันทึกรูปแบบบัตรคิวแล้ว ทุกตู้จะใช้ค่าใหม่ในการพิมพ์ครั้งถัดไป')}catch(ex){error.textContent=ex.message;error.classList.remove('hidden')}finally{btn.disabled=false}}}
async function render(root){if(!root||loading||root.querySelector('.ticket-template-form'))return;loading=true;root.innerHTML='<p class="system-settings-loading">กำลังโหลดรูปแบบบัตรคิว…</p>';try{const r=await kqApi('ticket-template-settings');state=r.data;defaults=r.defaults;form(root)}catch(ex){root.innerHTML=`<div class="auth-error">${e(ex.message)}</div>`}finally{loading=false}}
window.KQTicketTemplateSettings={render};
})();
